#define _POSIX_C_SOURCE 200809L
#include <glob.h>
#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zstd.h>
#define CAM 0x95358u
typedef struct{const uint8_t*p,*e;}R;typedef struct{uint32_t m;int32_t p[3],t[3];uint8_t tail[0x48];}S;static S s[1400];static size_t ns;static void die(const char*x){fprintf(stderr,"%s\n",x);exit(1);}static const uint8_t*take(R*r,size_t n){const uint8_t*p=r->p;if(p+n>r->e)die("truncated");r->p+=n;return p;}static uint8_t u8(R*r){return*take(r,1);}static uint16_t u16(R*r){uint16_t v;memcpy(&v,take(r,2),2);return v;}static uint32_t u32(R*r){uint32_t v;memcpy(&v,take(r,4),4);return v;}static uint64_t u64(R*r){uint64_t v;memcpy(&v,take(r,8),8);return v;}static int32_t i32(const uint8_t*p,size_t o){int32_t v;memcpy(&v,p+o,4);return v;}static uint8_t*inflate(const char*p,size_t*n){FILE*f=fopen(p,"rb");if(!f)die("open");fseek(f,0,SEEK_END);long z=ftell(f);rewind(f);uint8_t*q=malloc(z);fread(q,1,z,f);fclose(f);unsigned long long want=ZSTD_getFrameContentSize(q,z);uint8_t*d=malloc(want);size_t got=ZSTD_decompress(d,want,q,z);free(q);if(ZSTD_isError(got)||got!=want)die("zstd");*n=got;return d;}
static void key(uint32_t m){for(size_t i=0;i<ns;i++)if(s[i].m==m)printf("m%u pos=(%d,%d,%d) target=(%d,%d,%d)\n",m,s[i].p[0],s[i].p[1],s[i].p[2],s[i].t[0],s[i].t[1],s[i].t[2]);}
static int eq6(const S*a,const S*b){return !memcmp(a->p,b->p,24);}static int eqt(const S*a,const S*b){return !memcmp(a->t,b->t,12);}
static void diff_tail(uint32_t a,uint32_t b){S*x=NULL,*y=NULL;for(size_t i=0;i<ns;i++){if(s[i].m==a)x=&s[i];if(s[i].m==b)y=&s[i];}int n=0;if(x&&y)for(int i=0;i<0x48;i++)if(x->tail[i]!=y->tail[i])n++;printf("tail(+0x18..0x5f) byte differences m%u->m%u: %d\n",a,b,n);}
int main(int argc,char**argv){if(argc!=2)return 2;char pat[4096];snprintf(pat,sizeof(pat),"%s/chunks/*.tcap.zst",argv[1]);glob_t g={0};if(glob(pat,0,NULL,&g))die("chunks");uint8_t*dom[4]={0};for(size_t f=0;f<g.gl_pathc;f++){size_t n;uint8_t*b=inflate(g.gl_pathv[f],&n);R r={b,b+n};if(memcmp(take(&r,8),"DSTCAP01",8)||u32(&r)!=1)die("header");uint32_t mode=u32(&r);(void)u64(&r);uint32_t names=u32(&r);for(uint32_t i=0;i<names;i++)take(&r,u16(&r));while(r.p<r.e){if(u8(&r)!=1)die("tag");(void)u64(&r);(void)u64(&r);uint32_t m=u32(&r);(void)u32(&r);(void)u32(&r);for(uint32_t i=0;i<names;i++)(void)u32(&r);for(int d=0;d<3;d++){uint32_t id=u32(&r),sz=u32(&r),runs=u32(&r);take(&r,32);if(!dom[id])dom[id]=calloc(1,sz);for(uint32_t j=0;j<runs;j++){uint32_t o=u32(&r),l=u32(&r);memcpy(dom[id]+o,take(&r,l),l);}}uint64_t flows=u64(&r);for(uint64_t j=0;j<flows;j++){(void)u32(&r);if(mode==1)(void)u64(&r);else{(void)u32(&r);(void)u64(&r);}}S*x=&s[ns++];x->m=m;for(int k=0;k<3;k++){x->p[k]=i32(dom[1],CAM+k*4);x->t[k]=i32(dom[1],CAM+12+k*4);}memcpy(x->tail,dom[1]+CAM+0x18,0x48);}free(b);}globfree(&g);printf("frames=%zu\n",ns);uint32_t keys[]={1024,1040,1042,1044,1102,1150,1212,1214,1216,1222,1252,1254,1272};for(size_t i=0;i<sizeof(keys)/sizeof(keys[0]);i++)key(keys[i]);puts("-- stable full camera spans >=8 --");for(size_t i=0;i<ns;){size_t j=i+1;while(j<ns&&eq6(&s[i],&s[j]))j++;if(j-i>=8)printf("m%u..%u n=%zu\n",s[i].m,s[j-1].m,j-i);i=j;}puts("-- stable camera-target spans >=8 --");for(size_t i=0;i<ns;){size_t j=i+1;while(j<ns&&eqt(&s[i],&s[j]))j++;if(j-i>=8)printf("m%u..%u n=%zu target=(%d,%d,%d)\n",s[i].m,s[j-1].m,j-i,s[i].t[0],s[i].t[1],s[i].t[2]);i=j;}diff_tail(1040,1042);diff_tail(1102,1214);diff_tail(1214,1216);for(int i=1;i<=3;i++)free(dom[i]);return 0;}
